export function printBoxMask(subject,w,h,rect){if(subject.length!==w*h||!rect||['x','y','width','height'].some(k=>!Number.isFinite(rect[k]))||rect.x<0||rect.y<0||rect.width<=0||rect.height<=0||rect.x+rect.width>1.001||rect.y+rect.height>1.001)throw Error('Khung nhãn không hợp lệ.');const out=new Float32Array(w*h);for(let y=Math.floor(rect.y*h);y<Math.min(h,Math.ceil((rect.y+rect.height)*h));y++)for(let x=Math.floor(rect.x*w);x<Math.min(w,Math.ceil((rect.x+rect.width)*w));x++){const i=y*w+x;if(subject[i]>.98)out[i]=1;}return out;}
